		public List getKeyBytes(String key) {
			List keyBytes = new ArrayList();
			int leng = key.length();
			int iterator = (leng / 4);
			int remainder = leng % 4;
			int i = 0;
			for (i = 0; i < iterator; i++) {
				keyBytes.add(i, strToBt(key.substring(i * 4 + 0, i * 4 + 4)));
