			$('#password').select().focus();
		}
	});

	// 登录前页面设置，补充 hash
	var preUrl = $('#loginForm [name=__url]');
	if (preUrl.length > 0 && preUrl.val() != ''){
		preUrl.val(preUrl.val() + window.location.hash);
	}

});
